head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + 'searchbox1___input').placeholder == 'searchbox test1입니다.';
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'searchbox3___input').placeholder == 'searchbox test3입니다.';
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "400");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
